### Configs

**`database.js`**
```javascript
const mongoose = require('mongoose');

mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true, useUnifiedTopology: true });

const db = mongoose.connection;

db.on('error', (err) => {
  console.error(err);
});

db.once('open', () => {
  console.log('Connected to MongoDB');
});

module.exports = db;
```

**`auth.js`**
```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.header('Authorization').replace('Bearer ', '');
  const decoded = jwt.verify(token, process.env.JWT_SECRET);
  req.user = decoded;
  next();
};

module.exports = authenticate;
```

### Models

**`task.js`**
```javascript
const mongoose = require('mongoose');

const taskSchema = new mongoose.Schema({
  task_id: { type: String, required: true, unique: true },
  title: { type: String, required: true },
  priority: { type: String, required: true, enum: ['low', 'medium', 'high', 'critical'] },
  tags: { type: [String], required: true },
  estimated_hours: { type: Number, required: true },
  subtasks: [{ type: Object, required: true, subdocuments: true }]
});

const Task = mongoose.model('Task', taskSchema);

module.exports = Task;
```

**`user.js`**
```javascript
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  password: { type: String, required: true }
});

const User = mongoose.model('User', userSchema);

module.exports = User;
```

### Routes

**`task.js`**
```javascript
const express = require('express');
const Task = require('../models/task');
const authenticate = require('../config/auth');
const taskController = require('../controllers/taskController');

const router = express.Router();

router.get('/tasks', authenticate, taskController.getTasks);
router.get('/tasks/:id', authenticate, taskController.getTask);
router.post('/tasks', authenticate, taskController.createTask);
router.put('/tasks/:id', authenticate, taskController.updateTask);
router.delete('/tasks/:id', authenticate, taskController.deleteTask);

module.exports = router;
```

**`user.js`**
